"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["17768"],{74200(e){e.exports=JSON.parse('{"id":"FIN-969","slug":"term-sheet","term":"Term Sheet","also_known_as":[],"difficulty":"Intermediate","definition":"A term sheet is a short document that sets out the main terms and conditions of a proposed investment or transaction, used as the basis for negotiating final legal agreements.","explanation":["Term sheets are especially common in venture capital and private equity investments, but they are also used in loans, acquisitions and other deals. They summarise the key points the parties have agreed in principle, before lawyers draft the detailed contracts.","In a start-up funding round, a term sheet typically covers the amount being invested, the company\'s valuation, the type of shares being issued, liquidation preferences, board seats, voting rights, protections against dilution, rights to invest in future rounds and conditions that must be met before the deal closes.","For example, a venture capital firm might send a start-up a term sheet offering to invest 5 million at a pre-money valuation of 20 million, with one board seat and a 1x liquidation preference.","Most terms in a term sheet are not legally binding, although certain clauses, such as confidentiality and exclusivity, which prevents the company from negotiating with other investors for a period, often are. Founders should review term sheets carefully, often with legal advice, because terms beyond the headline valuation can significantly affect their control and eventual returns."],"note":"","total":1725,"prev":{"slug":"term-loan","term":"Term Loan"},"next":{"slug":"terminal-growth-rate","term":"Terminal Growth Rate"}}')}}]);